// Applied rules: [III④, C5]
// Skipped rules: [C3: The concrete C3 hits [0,1] are raw-byte loads from the advancing input cursor, not repeated invariant field/addr-chain reloads suitable for S2 hoisting. A body-local III④ slice view removes the raw-pointer cursor form that caused the aliasing gap at these sites, and S1 signature lift to references/slices would require caller-proof cross-function analysis on a `pub unsafe` API with lower payoff than the in-body rewrite.]
#[inline]
pub unsafe fn mz_adler32(
    mut adler: mz_ulong,
    mut ptr: *const c_uchar,
    mut buf_len: size_t,
) -> mz_ulong {
    let mut s1: mz_uint32 = (adler & 0xffff as mz_ulong) as mz_uint32;
    let mut s2: mz_uint32 = (adler >> 16 as c_int) as mz_uint32;
    let mut block_len: size_t = buf_len.wrapping_rem(5552 as size_t);
    if ptr.is_null() {
        return MZ_ADLER32_INIT as mz_ulong;
    }
    while buf_len != 0 {
        // SAFETY: `block_len` is derived from the explicit remaining input length (`buf_len`)
        // and is stable for this iteration; `ptr` is non-null due to the early return above;
        // this creates an immutable view only, and no mutable/reference alias to the same
        // memory is introduced across this region.
        let block = unsafe { core::slice::from_raw_parts(ptr, block_len) };

        let n = block.len() as u64;
        let mut bsum: u64 = 0;
        let mut bwsum: u64 = 0;

        for (j, &byte) in block.iter().enumerate() {
            let v = byte as u64;
            bsum = bsum.wrapping_add(v);
            bwsum = bwsum.wrapping_add((j as u64).wrapping_mul(v));
        }

        let s1u = (s1 as u64).wrapping_add(bsum);
        let s2u = (s2 as u64)
            .wrapping_add(n.wrapping_mul(s1 as u64))
            .wrapping_add(n.wrapping_mul(bsum))
            .wrapping_sub(bwsum);

        s1 = (s1u.wrapping_rem(65521_u64)) as mz_uint32;
        s2 = (s2u.wrapping_rem(65521_u64)) as mz_uint32;

        // SAFETY: advancing by exactly `block_len` stays within the same caller-provided
        // input region for this iteration because `block_len` was used to form `block`.
        ptr = unsafe { ptr.add(block_len) };
        buf_len = buf_len.wrapping_sub(block_len);
        block_len = 5552 as size_t;
    }
    (s2 << 16 as c_int).wrapping_add(s1) as mz_ulong
}

